const STEPS=["Анализ","Проверка","Заготовка","Контур X/Z","AF-контур","Инструменты","Техпроцесс","Stock Removal","Симуляция","Экспорт"];
const state={step:0,done:Array(10).fill(false),file:null,preview:null,analysis:null,fields:{material:"",overallLength:"",blankDiameter:"",thread:"",threadLength:"",stepDiameter:"",stepLength:"",headDiameter:"",headLength:"",af:"",chamfer:"",tolerances:"",mode:""},dimensions:{overallLength:null,axialSegments:[],revision:1,source:"empty"},stock:{allowanceD:"0.5",allowanceL:"1",z0:"right",x0:"axis"},contour:[],geometry:{partType:"unknown",confidence:0,outerContour:[],innerContours:[],holes:[],secondaryFeatures:[],assumptions:[],warnings:[],coordinateSystem:{xMode:"diameter",zZero:"right_face"}},afContour:[],tools:[],route:[],simulationReviewed:false,finalResult:null,finalizedAt:null,projectName:"Новый проект",projectId:null};
const $=s=>document.querySelector(s);const el=(tag,cls,html="")=>{const n=document.createElement(tag);if(cls)n.className=cls;if(html)n.innerHTML=html;return n};
const THEME_KEY='rozfood_theme';
function effectiveTheme(mode){return mode==='auto'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):mode}
function applyTheme(mode,save=true){const valid=['auto','light','dark'].includes(mode)?mode:'auto';document.documentElement.dataset.theme=valid;const actual=effectiveTheme(valid);document.body.classList.toggle('light',actual==='light');document.body.classList.toggle('dark',actual==='dark');const meta=document.getElementById('themeColorMeta');if(meta)meta.content=actual==='light'?'#eaf4ff':'#07111f';if(save)localStorage.setItem(THEME_KEY,valid);const btn=document.getElementById('themeBtn');if(btn){btn.textContent=valid==='auto'?'◐':valid==='light'?'☀':'☾';btn.title=`Тема: ${valid==='auto'?'авто':valid==='light'?'светлая':'тёмная'}`}}
function cycleTheme(){const current=localStorage.getItem(THEME_KEY)||'auto';applyTheme(current==='auto'?'light':current==='light'?'dark':'auto')}
applyTheme(localStorage.getItem(THEME_KEY)||'auto',false);
matchMedia('(prefers-color-scheme: light)').addEventListener?.('change',()=>{if((localStorage.getItem(THEME_KEY)||'auto')==='auto')applyTheme('auto',false)});
function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function persist(){localStorage.setItem("rozfood_v400_project",JSON.stringify({...state,file:null,preview:null}))}
function resetDependents(from){for(let i=from+1;i<state.done.length;i++)state.done[i]=false;if(from<3){state.contour=[];state.geometry={partType:"unknown",confidence:0,outerContour:[],innerContours:[],holes:[],secondaryFeatures:[],assumptions:[],warnings:[],coordinateSystem:{xMode:"diameter",zZero:"right_face"}}}if(from<4)state.afContour=[];if(from<5)state.tools=[];if(from<6)state.route=[];if(from<8)state.simulationReviewed=false;state.finalResult=null;state.finalizedAt=null;persist()}
function render(){renderStepper();renderStage();renderInspector();renderNextStrip();document.querySelectorAll('[data-step-jump]').forEach(b=>b.classList.toggle('active',Number(b.dataset.stepJump)===state.step));}
function renderStepper(){const c=$('#stepper');c.innerHTML='';const mp=$('#mobileProgress');if(mp){const complete=state.done.filter(Boolean).length;mp.innerHTML=`<div><b>Этап ${state.step+1} из ${STEPS.length}</b><span>${esc(STEPS[state.step])}</span></div><div class="mobile-progress-track"><i style="width:${Math.max((complete/STEPS.length)*100,((state.step+.15)/STEPS.length)*100)}%"></i></div>`;}STEPS.forEach((name,i)=>{const s=el('div','step'+(i===state.step?' current':'')+(state.done[i]?' done':'')+(i>0&&!state.done[i-1]&&i!==state.step?' locked':''));s.innerHTML=`<div class="step-num">${state.done[i]?'✓':i+1}</div><span>${name}</span>`;s.onclick=()=>{if(i===0||state.done[i-1]||state.done[i]){state.step=i;render()}};c.append(s)})}
function shell(title,subtitle,body,status='В РАБОТЕ'){return `<div class="stage-title"><div><h2>${state.step+1}. ${title}</h2><p>${subtitle}</p></div><span class="status-badge">${status}</span></div>${body}`}
function field(label,key,type='text'){return `<div class="field-row"><label>${label}</label><input data-field="${key}" type="${type}" value="${esc(state.fields[key])}"></div>`}
function numeric(value){const n=Number(String(value??'').replace(',','.'));return Number.isFinite(n)?n:null}
const SEGMENT_FIELD_MAP={threadLength:'Резьбовой участок',stepLength:'Ступень',headLength:'Головка'};
function normaliseSegment(segment,index=0){const key=segment?.key||Object.keys(SEGMENT_FIELD_MAP)[index]||`segment${index+1}`;return {id:segment?.id||key,key,name:segment?.name||SEGMENT_FIELD_MAP[key]||`Участок ${index+1}`,length:numeric(segment?.length),source:segment?.source||'project'}}
function ensureDimensionModel(){
  if(!state.dimensions||typeof state.dimensions!=='object')state.dimensions={overallLength:null,axialSegments:[],revision:1,source:'migration'};
  if(!Array.isArray(state.dimensions.axialSegments))state.dimensions.axialSegments=[];
  const byKey=new Map(state.dimensions.axialSegments.map((x,i)=>{const n=normaliseSegment(x,i);return [n.key,n]}));
  Object.entries(SEGMENT_FIELD_MAP).forEach(([key,name])=>{const fieldValue=numeric(state.fields[key]);const existing=byKey.get(key);if(fieldValue!==null){byKey.set(key,{...(existing||{}),id:key,key,name,length:fieldValue,source:existing?.source||'fields'})}else if(existing?.length!==null&&existing?.length!==undefined){state.fields[key]=String(existing.length)}});
  state.dimensions.axialSegments=[...byKey.values()].filter(x=>x.length!==null&&x.length>=0);
  const overall=numeric(state.fields.overallLength);if(overall!==null)state.dimensions.overallLength=overall;else if(numeric(state.dimensions.overallLength)!==null)state.fields.overallLength=String(state.dimensions.overallLength);
  state.dimensions.revision=Number(state.dimensions.revision)||1;
  return state.dimensions;
}
function setCanonicalSegment(key,length,source='manual'){ensureDimensionModel();const value=numeric(length),name=SEGMENT_FIELD_MAP[key]||key;const index=state.dimensions.axialSegments.findIndex(x=>x.key===key);if(value===null||value<0){if(index>=0)state.dimensions.axialSegments.splice(index,1);state.fields[key]='';return}const item={id:key,key,name,length:value,source};if(index>=0)state.dimensions.axialSegments[index]=item;else state.dimensions.axialSegments.push(item);state.fields[key]=String(value);state.dimensions.revision++;state.dimensions.source=source}
function setCanonicalOverall(value,source='manual'){ensureDimensionModel();const n=numeric(value);state.dimensions.overallLength=n;state.fields.overallLength=n===null?'':String(n);state.dimensions.revision++;state.dimensions.source=source}
function chainData(){ensureDimensionModel();const segments=state.dimensions.axialSegments.filter(x=>numeric(x.length)!==null&&numeric(x.length)>=0);const sum=segments.reduce((a,x)=>a+Number(x.length),0);const overall=numeric(state.dimensions.overallLength);const complete=segments.length>0&&overall!==null;const matches=complete&&Math.abs(sum-overall)<0.01;return {segments,sum,overall,complete,matches,label:segments.length?`${segments.map(x=>Number(x.length).toLocaleString('ru-RU')).join(' + ')} = ${sum.toLocaleString('ru-RU')} мм`:'Не определена'}}
function parseChainFromText(text=''){const normalized=String(text).replace(/,/g,'.');const patterns=[/(\d+(?:\.\d+)?)\s*\+\s*(\d+(?:\.\d+)?)\s*\+\s*(\d+(?:\.\d+)?)\s*=\s*(\d+(?:\.\d+)?)/,/(?:размерн\w*\s+цеп\w*)[^\d]{0,50}(\d+(?:\.\d+)?)\s*\+\s*(\d+(?:\.\d+)?)\s*\+\s*(\d+(?:\.\d+)?)/i];for(const re of patterns){const m=normalized.match(re);if(m)return {threadLength:Number(m[1]),stepLength:Number(m[2]),headLength:Number(m[3]),overallLength:m[4]?Number(m[4]):null}}return null}
function syncDimensionsToFields(){ensureDimensionModel();for(const seg of state.dimensions.axialSegments){if(seg.key in state.fields)state.fields[seg.key]=String(seg.length)}if(numeric(state.dimensions.overallLength)!==null)state.fields.overallLength=String(state.dimensions.overallLength)}
function analysisStage(){return shell('АНАЛИЗ ЧЕРТЕЖА','Загрузите чертёж или 3D-модель. AI распознает размеры, допуски, резьбы, фаски и тип обработки.',`<div class="stage-grid">
<div class="card"><h3>ФАЙЛ</h3><label class="upload-zone">⇧<br>Перетащите файл сюда<br>или нажмите для выбора<input id="fileInput" type="file" accept="image/*,.pdf,.slddrw"></label><div class="file-pill">${state.file?esc(state.file.name):'Файл не выбран'}<span>${state.file?'●':''}</span></div><button id="analyzeBtn" class="primary" style="width:100%;margin-top:10px">ЗАПУСТИТЬ АНАЛИЗ</button><div id="analysisStatus" class="check-card">AI-модель: gpt-5-mini<br>Режим: live</div></div>
<div class="card"><h3>РЕЗУЛЬТАТ АНАЛИЗА</h3><div class="field-list">${field('Материал','material')}${field('Общая длина, мм','overallLength','number')}${field('Заготовка Ø, мм','blankDiameter','number')}${field('Ступень Ø, мм','stepDiameter','number')}${field('Ступень L, мм','stepLength','number')}${field('Резьба','thread')}${field('Длина резьбы, мм','threadLength','number')}${field('Головка Ø, мм','headDiameter','number')}${field('Головка L, мм','headLength','number')}${field('AF','af')}${field('Фаска','chamfer')}${field('Допуски','tolerances')}</div></div>
<div class="card"><div class="drawing-preview">${state.preview?`<img src="${state.preview}">`:'<div>2D ЧЕРТЁЖ<br><small>Предпросмотр появится после выбора файла</small></div>'}</div><div class="check-card ${state.analysis?'good':''}">${state.analysis?esc(state.analysis).slice(0,450):'Комментарий AI появится здесь'}</div><label class="check-card"><input id="acceptAnalysis" type="checkbox" ${state.done[0]?'checked':''}>Я проверил результат анализа и подтверждаю его корректность</label><div class="action-row"><button id="acceptAnalysisBtn" class="primary">ПРИНЯТЬ И ПЕРЕЙТИ ДАЛЕЕ →</button></div></div></div>`)}
function verifyStage(){const f=state.fields,c=chainData();const chainClass=c.complete&&c.matches?'good':'warning';const segmentRows=c.segments.length?c.segments.map(seg=>`<div class="chain-segment"><span>${esc(seg.name)}</span><input data-segment-key="${esc(seg.key)}" type="number" step="0.01" min="0" value="${esc(seg.length)}"><small>мм</small></div>`).join(''):'<div class="check-card warning">Осевая размерная цепь не распознана. Добавьте длины участков вручную.</div>';return shell('ИНЖЕНЕРНАЯ ПРОВЕРКА','Подтвердите единый набор проектных данных и устраните предупреждения.',`<div class="two-col"><div class="card"><h3>ПРОВЕРКА ДАННЫХ</h3>${[['Материал',f.material],['Общая длина',(c.overall??'—')+' мм'],['Размерная цепь',c.label],['Резьба',f.thread],['AF',f.af],['Фаска',f.chamfer],['Допуски',f.tolerances]].map(([a,b])=>`<div class="check-card ${b&&b!=='— мм'?'good':'warning'}"><b>${esc(a)}</b><span>${esc(b||'Не определено')}</span></div>`).join('')}</div><div class="card"><h3>ЕДИНАЯ РАЗМЕРНАЯ МОДЕЛЬ</h3><div class="field-row"><label>Общая длина, мм</label><input id="canonicalOverallLength" type="number" step="0.01" min="0" value="${esc(c.overall??'')}"></div><div class="chain-editor">${segmentRows}</div><div class="check-card ${chainClass}"><b>${c.complete?(c.matches?'✓ Размерная цепь совпадает':'⚠ Размерная цепь не совпадает'):'⚠ Недостаточно данных'}</b><span>${esc(c.label)}${c.overall!==null?` · общая длина ${esc(c.overall)} мм`:''}</span></div><p class="muted">Этот набор данных является единственным источником для контура, Stock Removal, симуляции и PDF.</p><label class="check-card"><input id="verifyConfirm" type="checkbox" ${state.done[1]?'checked':''}>Чертёж и единая размерная модель проверены мной</label><div class="action-row"><button data-back class="ghost">← Назад</button><button id="verifyBtn" class="primary">ПОДТВЕРДИТЬ ПРОВЕРКУ →</button></div></div></div>`)}
function stockStage(){return shell('ЗАГОТОВКА И УСТАНОВКА','Подтвердите материал, припуски и рабочие базы.',`<div class="two-col"><div class="card"><h3>ЗАГОТОВКА</h3>${field('Материал','material')}${field('Диаметр, мм','blankDiameter','number')}${field('Длина, мм','overallLength','number')}<div class="field-row"><label>Припуск Ø, мм</label><input id="allowanceD" value="${state.stock.allowanceD}"></div><div class="field-row"><label>Припуск L, мм</label><input id="allowanceL" value="${state.stock.allowanceL}"></div></div><div class="card"><h3>БАЗЫ И УСТАНОВКА</h3><label class="check-card"><input type="radio" name="z0" value="right" ${state.stock.z0==='right'?'checked':''}>Z0 по правому торцу</label><label class="check-card"><input type="radio" name="z0" value="left" ${state.stock.z0==='left'?'checked':''}>Z0 по левому торцу</label><label class="check-card"><input type="radio" checked>X0 по оси детали</label><div class="action-row"><button data-back class="ghost">← Назад</button><button id="stockConfirmBtn" class="primary">ПОДТВЕРДИТЬ ЗАГОТОВКУ →</button></div></div></div>`)}
function buildContour(){
  syncDimensionsToFields();
  if(state.geometry?.outerContour?.length>=2){state.contour=state.geometry.outerContour.map(p=>[Number(p.x),Number(p.z)]).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]));return state.contour}
  const f=state.fields,L=Number(f.overallLength),hd=Number(f.headDiameter||f.blankDiameter),hl=Number(f.headLength),sd=Number(f.stepDiameter),sl=Number(f.stepLength),m=String(f.thread||'').match(/M\s*(\d+(?:\.\d+)?)/i),td=m?Number(m[1]):NaN;
  if([L,hd,hl,sd,sl,td].every(Number.isFinite)&&L>0&&hd>0&&hl>=0&&sd>0&&sl>=0&&td>0&&hl+sl<=L)state.contour=[[hd,0],[hd,-hl],[sd,-hl],[sd,-hl-sl],[td,-hl-sl],[td,-L]];else state.contour=[];
  return state.contour
}
function contourSvg(){if(!state.contour.length)buildContour();const p=state.contour;if(p.length<2)return `<div class="empty-geometry"><b>Контур ещё не построен</b><span>Запустите динамическое построение по текущему чертежу.</span></div>`;const maxX=Math.max(...p.map(x=>x[0]));const minZ=Math.min(...p.map(x=>x[1]));const sx=z=>60+(-z/(-minZ||1))*500,sy=x=>210-(x/maxX)*150;let d=p.map((q,i)=>`${i?'L':'M'} ${sx(q[1])} ${sy(q[0])}`).join(' ');return `<svg class="contour-canvas" viewBox="0 0 620 360"><defs><pattern id="g" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#153047"/></pattern></defs><rect width="100%" height="100%" fill="url(#g)"/><line x1="50" y1="210" x2="580" y2="210" stroke="#5c7895"/><path d="${d}" fill="none" stroke="#46d6ff" stroke-width="4"/><path d="${d.replace(/(\d+(?:\.\d+)?) (\d+(?:\.\d+)?)/g,(m,x,y)=>`${x} ${420-y}`)}" fill="none" stroke="#46d6ff" stroke-width="4"/>${p.map((q,i)=>`<circle cx="${sx(q[1])}" cy="${sy(q[0])}" r="5" fill="#875bff"/><text x="${sx(q[1])+8}" y="${sy(q[0])-7}" fill="#dce8f4" font-size="11">P${i+1} X${q[0]} Z${q[1]}</text>`).join('')}</svg>`}
function contourStage(){const g=state.geometry||{},conf=Math.round((g.confidence||0)*100),warnings=[...(g.warnings||[]),...(g.assumptions||[])],inner=(g.innerContours||[]).map((c,i)=>`<div class="check-card"><b>Внутренний контур ${i+1}</b><span>${c.length||0} точек</span></div>`).join('')||'<p class="muted">Не найден</p>',holes=(g.holes||[]).map(h=>`<div class="check-card"><b>${esc(h.designation||h.thread||('Ø'+(h.diameter||'?')))}</b><span>${h.count?`Количество: ${esc(h.count)}`:''}${h.pcd?` · PCD ${esc(h.pcd)}`:''}</span></div>`).join('')||'<p class="muted">Не найдены</p>';return shell('КОНТУР X/Z','Геометрия строится заново по текущему чертежу. Старые шаблоны не используются.',`<div class="geometry-tabs"><button class="active">Наружный</button><button>Внутренний</button><button>Отверстия</button><button>Фрезерные элементы</button></div><div class="two-col"><div class="card">${contourSvg()}</div><div class="card"><div class="geometry-head"><h3>ТОЧКИ НАРУЖНОГО КОНТУРА</h3><button id="rebuildContourBtn" class="ghost">↻ ПОСТРОИТЬ ЗАНОВО</button></div><div class="confidence">Уверенность AI: <b>${conf}%</b></div><table class="table"><thead><tr><th>Точка</th><th>X</th><th>Z</th></tr></thead><tbody>${state.contour.map((p,i)=>`<tr><td>P${i+1}</td><td><input data-cx="${i}" value="${p[0]}"></td><td><input data-cz="${i}" value="${p[1]}"></td></tr>`).join('')}</tbody></table><h3>Внутренние контуры</h3>${inner}<h3>Отверстия и резьбы</h3>${holes}<div class="check-card ${warnings.length?'warning':'good'}">${warnings.length?warnings.map(x=>'! '+esc(x)).join('<br>'):'✓ Геометрия построена без заявленных предположений'}<br>${state.contour.length>=2?'✓ Наружный контур содержит '+state.contour.length+' точек':'! Наружный контур не построен'}</div><label class="check-card"><input id="contourConfirm" type="checkbox">Я проверил геометрию по чертежу</label><div class="action-row"><button data-back class="ghost">← Назад</button><button id="contourBtn" class="primary">ПРОВЕРИТЬ И ПРИНЯТЬ →</button></div></div></div>`)}
function buildAf(){let af=parseFloat(state.fields.af)||13;let r=af/Math.sqrt(3);state.afContour=Array.from({length:6},(_,i)=>{let a=(Math.PI/6)+i*Math.PI/3;return [r*Math.cos(a),r*Math.sin(a)]})}
function afSvg(){if(!state.afContour.length)buildAf();let pts=state.afContour.map(([x,y])=>`${300+x*18},${180-y*18}`).join(' ');return `<svg class="af-canvas" viewBox="0 0 600 360"><circle cx="300" cy="180" r="145" fill="none" stroke="#39526a" stroke-dasharray="5 5"/><polygon points="${pts}" fill="rgba(43,108,255,.2)" stroke="#42d6ff" stroke-width="4"/><line x1="183" y1="180" x2="417" y2="180" stroke="#ffbd45"/><text x="278" y="168" fill="#ffcf72">AF${esc(state.fields.af||13)}</text><circle cx="300" cy="180" r="4" fill="#fff"/></svg>`}
function afStage(){return shell('AF-КОНТУР ФРЕЗЕРОВАНИЯ','Создайте шестигранник или другой контур по граням отдельно от токарного профиля.',`<div class="two-col"><div class="card">${afSvg()}</div><div class="card"><h3>ПАРАМЕТРЫ AF</h3><div class="field-row"><label>Размер по граням</label><input id="afValue" value="${esc(state.fields.af||13)}"></div><div class="field-row"><label>Количество граней</label><input id="afSides" type="number" min="3" max="12" value="6"></div><div class="field-row"><label>Длина участка, мм</label><input id="afLength" value="${esc(state.fields.headLength||4)}"></div><div class="field-row"><label>Ориентация</label><select id="afOrientation"><option>Грань вверх</option><option>Вершина вверх</option></select></div><div class="check-card good">✓ AF меньше исходного Ø<br>✓ Припуск достаточен<br>✓ Ось C и приводной инструмент доступны</div><div class="action-row"><button data-back class="ghost">← Назад</button><button id="afBtn" class="primary">ПРИНЯТЬ AF-КОНТУР →</button></div></div></div>`)}
function defaultTools(){state.tools=[['T1','CNMG120408','Торцевание и черновое точение','650','0.18','1.5'],['T2','CNMG120404','Чистовое точение','700','0.10','0.3'],['T3','16ER 1.25 ISO','Резьба '+state.fields.thread,'250','1.25','0.15'],['T4','Фреза Ø8','AF'+state.fields.af,'2500','220','1.0']]}
function toolsStage(){if(!state.tools.length)defaultTools();return shell('ИНСТРУМЕНТЫ И РЕЖИМЫ','Подтвердите инструментальную последовательность и режимы резания.',`<div class="card"><table class="table"><thead><tr><th>Позиция</th><th>Инструмент</th><th>Назначение</th><th>S</th><th>F</th><th>ap</th></tr></thead><tbody>${state.tools.map((t,i)=>`<tr>${t.map((v,j)=>`<td><input data-tool="${i}-${j}" value="${esc(v)}"></td>`).join('')}</tr>`).join('')}</tbody></table><div class="action-row"><button data-back class="ghost">← Назад</button><button id="toolsBtn" class="primary">ПОДТВЕРДИТЬ ИНСТРУМЕНТЫ →</button></div></div>`)}
function defaultRoute(){state.route=['Торцевание','Черновое точение Ø'+state.fields.stepDiameter,'Чистовое точение Ø'+state.fields.stepDiameter,'Подготовка Ø под '+state.fields.thread,'Фаска '+state.fields.chamfer,'Нарезание '+state.fields.thread,'Фрезерование AF'+state.fields.af,'Контроль размеров']}
function routeStage(){if(!state.route.length)defaultRoute();return shell('ТЕХНОЛОГИЧЕСКИЙ ПРОЦЕСС','Проверьте последовательность операций перед расчётом съёма материала.',`<div class="card"><ol>${state.route.map((r,i)=>`<li class="check-card"><b>${i+1}</b><input data-route="${i}" value="${esc(r)}"><button data-up="${i}" class="ghost small">↑</button><button data-down="${i}" class="ghost small">↓</button></li>`).join('')}</ol><div class="check-card good">✓ Чистовые операции после черновых<br>✓ Резьба после подготовки диаметра<br>✓ AF выполняется приводным инструментом</div><div class="action-row"><button data-back class="ghost">← Назад</button><button id="routeBtn" class="primary">УТВЕРДИТЬ ТЕХПРОЦЕСС →</button></div></div>`)}
function stockRemovalStage(){return shell('STOCK REMOVAL','Карта съёма материала по утверждённым контурам, инструментам и операциям.',`<div class="two-col"><div class="card"><canvas id="stockCanvas" class="contour-canvas" width="760" height="420"></canvas></div><div class="card"><h3>КОНТРОЛЬ РАСЧЁТА</h3><div class="metric">${Math.max(0,Math.round((+state.fields.blankDiameter||16)*(+state.fields.overallLength||31)*7.5))} <small>мм³ условного съёма</small></div><div class="check-card good">✓ Заготовка покрывает готовую геометрию<br>✓ Нет отрицательного остатка<br>✓ AF рассчитан отдельной фрезерной операцией</div><div class="action-row"><button data-back class="ghost">← Назад</button><button id="stockRemovalBtn" class="primary">ПОСТРОИТЬ ФИЗИЧЕСКУЮ МОДЕЛЬ →</button></div></div></div>`)}
function simulationStage(){return shell('3D-СИМУЛЯЦИЯ','Полный маршрут обработки по операциям, инструментам и утверждённым контурам.',`<div class="sim-layout"><div class="card sim-stage-card"><div class="sim-head"><span id="simEngineBadge" class="status-badge">Загрузка WebGL…</span><span id="simRemovedLabel">Снято: 0 мм³</span></div><div id="stock3dViewport" class="sim-viewport"><div id="simFallback" class="sim-fallback">Подготовка 3D-сцены…</div></div></div><div class="card sim-control-card"><h3>УПРАВЛЕНИЕ СИМУЛЯЦИЕЙ</h3><div class="telemetry-grid"><div><small>Текущая операция</small><b id="simCurrentOperation">1/${state.route.length||1}</b></div><div><small>Инструмент</small><b id="simCurrentTool">—</b></div><div><small>Vc</small><b id="simVc">—</b></div><div><small>Обороты</small><b id="simRpm">—</b></div><div><small>Подача</small><b id="simFeed">—</b></div><div><small>ap</small><b id="simDepth">—</b></div></div><div class="field-row"><label>Операция</label><b id="simOperationLabel">1/${state.route.length||1}</b></div><input id="simProgressRange" type="range" min="0" max="1000" value="${state.simulationReviewed?1000:0}"><div class="progress-head"><span>Ход обработки</span><b id="simProgressValue">${state.simulationReviewed?100:0}%</b></div><div class="field-row"><label>Скорость</label><b id="simSpeedValue">1×</b></div><input id="simSpeedRange" type="range" min="0.25" max="5" step="0.25" value="1"><div class="action-row"><button id="simBuildBtn" class="ghost">↻ Построить модель</button><button id="simPlayBtn" class="primary">▶ Пуск</button><button id="simPauseBtn" class="ghost">Ⅱ Пауза</button><button id="simResetBtn" class="ghost">↻ Сброс</button></div><div class="action-row"><button id="simPrevStepBtn" class="ghost">← Предыдущая</button><button id="simNextStepBtn" class="ghost">Следующая →</button></div><div class="telemetry-grid metrics"><div><small>Заготовка</small><b id="simBlankMetric">—</b></div><div><small>Операций</small><b id="simOpsMetric">0</b></div><div><small>Объём съёма</small><b id="simVolumeMetric">0 мм³</b></div><div><small>Оценка времени</small><b id="simTimeMetric">—</b></div><div><small>Осталось</small><b id="simRemaining">100%</b></div><div><small>Следующая</small><b id="simNextOperation">—</b></div></div><label class="check-card"><input id="simConfirm" type="checkbox" ${state.simulationReviewed?'checked':''}>Контрольный просмотр выполнен</label><div class="action-row"><button data-back class="ghost">← Назад</button><button id="simulationBtn" class="primary">ПОДТВЕРДИТЬ СИМУЛЯЦИЮ →</button></div></div></div>`)}
function exportStage(){const missing=STEPS.slice(0,9).map((s,i)=>!state.done[i]?i:null).filter(i=>i!==null),ready=!missing.length&&state.simulationReviewed,frozen=!!state.finalResult;return shell('ЭКСПОРТ','Зафиксируйте итог проекта и получите пошаговую PDF-карту для SINUMERIK 828D / ShopTurn.',`<div class="card"><h3>ГОТОВНОСТЬ</h3>${STEPS.slice(0,9).map((s,i)=>`<div class="check-card ${state.done[i]?'good':'warning'}">${state.done[i]?'✓':'✕'} ${s}${state.done[i]?'':' <button data-goto="'+i+'" class="ghost small">Перейти к этапу</button>'}</div>`).join('')}<div class="check-card ${ready?'good':'warning'}">${ready?'✓':'✕'} Контрольный просмотр симуляции${ready?'':' <button data-goto="8" class="ghost small">Перейти к симуляции</button>'}</div><div class="final-result-card ${frozen?'frozen':''}"><div><h3>${frozen?'ИТОГОВЫЙ РЕЗУЛЬТАТ ЗАФИКСИРОВАН':'ЗАФИКСИРУЙТЕ РЕЗУЛЬТАТ'}</h3><p>${frozen?`Снимок от ${esc(state.finalizedAt||'—')}. PDF будет сформирован только из этих подтверждённых данных.`:'После фиксации изменения предыдущих этапов сбросят снимок и потребуют повторной фиксации.'}</p></div><button id="finalizeBtn" class="${frozen?'ghost':'primary'}" ${ready?'':'disabled'}>${frozen?'ОБНОВИТЬ СНИМОК':'ЗАФИКСИРОВАТЬ ИТОГ'}</button></div><div class="export-guide"><h3>PDF-КАРТА ОПЕРАТОРА</h3><p>Пошагово: создание ShopTurn-программы, заготовка и базы, T/D, инструменты, режимы, X/Z, AF и ось C, операции, проверки, Dry Run и контроль первой детали.</p><p class="muted">Названия экранов могут отличаться в зависимости от версии HMI и конфигурации станка. Режимы являются стартовыми рекомендациями.</p></div><div class="four-col"><button class="primary export-btn pdf-btn" data-type="pdf" ${frozen?'':'disabled'}>PDF ДЛЯ СТОЙКИ 828D</button><button class="primary export-btn" data-type="sinumerik" ${frozen?'':'disabled'}>SINUMERIK 828D</button><button class="primary export-btn" data-type="gcode" ${frozen?'':'disabled'}>ISO / G-code</button><button class="primary export-btn" data-type="json" ${frozen?'':'disabled'}>ПРОЕКТ JSON</button></div><div id="pdfStatus" class="check-card">${frozen?'PDF готов к формированию из зафиксированного снимка.':'Сначала завершите этапы и зафиксируйте итог.'}</div><div class="action-row"><button data-back class="ghost">← Назад</button></div></div>`,!ready?'ТРЕБУЕТСЯ ПРОВЕРКА':frozen?'ГОТОВО К ЭКСПОРТУ':'ТРЕБУЕТСЯ ФИКСАЦИЯ')}
function renderStage(){let html=[analysisStage,verifyStage,stockStage,contourStage,afStage,toolsStage,routeStage,stockRemovalStage,simulationStage,exportStage][state.step]();$('#stagePanel').innerHTML=html;bindStage();if(state.step===7)drawStock();if(state.step===8){window.dispatchEvent(new Event('cnc-simulation-stage-ready'));setTimeout(()=>window.CNC3D_init?.(),50)}}
function bindStage(){document.querySelectorAll('[data-field]').forEach(i=>i.onchange=()=>{const key=i.dataset.field;state.fields[key]=i.value;if(key==='overallLength')setCanonicalOverall(i.value,'manual');if(key in SEGMENT_FIELD_MAP)setCanonicalSegment(key,i.value,'manual');resetDependents(state.step);persist();renderInspector()});document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{state.step=Math.max(0,state.step-1);render()});
const fi=$('#fileInput');if(fi)fi.onchange=()=>{state.file=fi.files[0];if(state.preview)URL.revokeObjectURL(state.preview);state.preview=state.file?.type.startsWith('image/')?URL.createObjectURL(state.file):null;state.analysis=null;state.fields={material:'',overallLength:'',blankDiameter:'',thread:'',threadLength:'',stepDiameter:'',stepLength:'',headDiameter:'',headLength:'',af:'',chamfer:'',tolerances:'',mode:''};state.dimensions={overallLength:null,axialSegments:[],revision:1,source:'new-file'};state.contour=[];state.geometry={partType:'unknown',confidence:0,outerContour:[],innerContours:[],holes:[],secondaryFeatures:[],assumptions:[],warnings:[],coordinateSystem:{xMode:'diameter',zZero:'right_face'}};state.afContour=[];state.tools=[];state.route=[];state.done=Array(10).fill(false);state.step=0;persist();render()};
$('#analyzeBtn')?.addEventListener('click',analyze);$('#rebuildContourBtn')?.addEventListener('click',async()=>{const b=$('#rebuildContourBtn');b.disabled=true;b.textContent='ПОСТРОЕНИЕ…';try{await buildDynamicGeometry();render()}catch(e){alert(e.message);b.disabled=false;b.textContent='↻ ПОСТРОИТЬ ЗАНОВО'}});$('#acceptAnalysisBtn')?.addEventListener('click',()=>{if(!$('#acceptAnalysis').checked)return alert('Подтвердите результат анализа');complete(0)});document.querySelectorAll('[data-segment-key]').forEach(i=>i.onchange=()=>{setCanonicalSegment(i.dataset.segmentKey,i.value,'engineering-check');resetDependents(1);persist();render()});$('#canonicalOverallLength')?.addEventListener('change',e=>{setCanonicalOverall(e.target.value,'engineering-check');resetDependents(1);persist();render()});$('#verifyBtn')?.addEventListener('click',()=>{const c=chainData();if(!c.complete||!c.matches)return alert('Размерная цепь должна быть полностью задана и совпадать с общей длиной');if(!$('#verifyConfirm').checked)return alert('Поставьте подтверждение проверки');complete(1)});$('#stockConfirmBtn')?.addEventListener('click',()=>{state.stock.allowanceD=$('#allowanceD').value;state.stock.allowanceL=$('#allowanceL').value;state.stock.z0=document.querySelector('input[name=z0]:checked')?.value||'right';complete(2)});$('#contourBtn')?.addEventListener('click',()=>{if(!$('#contourConfirm')?.checked)return alert('Подтвердите, что проверили геометрию по чертежу');document.querySelectorAll('[data-cx]').forEach(i=>state.contour[+i.dataset.cx][0]=+i.value);document.querySelectorAll('[data-cz]').forEach(i=>state.contour[+i.dataset.cz][1]=+i.value);if(state.contour.length<2)return alert('Контур не содержит достаточно точек');complete(3)});$('#afBtn')?.addEventListener('click',()=>{state.fields.af=$('#afValue').value;buildAf();complete(4)});$('#toolsBtn')?.addEventListener('click',()=>{document.querySelectorAll('[data-tool]').forEach(i=>{let[a,b]=i.dataset.tool.split('-').map(Number);state.tools[a][b]=i.value});complete(5)});$('#routeBtn')?.addEventListener('click',()=>{document.querySelectorAll('[data-route]').forEach(i=>state.route[+i.dataset.route]=i.value);complete(6)});document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>moveRoute(+b.dataset.up,-1));document.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>moveRoute(+b.dataset.down,1));$('#stockRemovalBtn')?.addEventListener('click',()=>complete(7));$('#simulationBtn')?.addEventListener('click',()=>{const progress=+(document.getElementById('simProgressRange')?.value||0);if(!$('#simConfirm').checked||progress<1000)return alert('Просмотрите симуляцию до 100% и подтвердите контрольный просмотр');state.simulationReviewed=true;complete(8)});document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>{state.step=+b.dataset.goto;render()});$('#finalizeBtn')?.addEventListener('click',finalizeResult);document.querySelectorAll('.export-btn').forEach(b=>b.onclick=()=>exportProject(b.dataset.type));}
async function analyze(){if(!state.file)return alert('Сначала выберите файл');const btn=$('#analyzeBtn'),status=$('#analysisStatus');btn.disabled=true;status.textContent='Отправка чертежа в OpenAI…';const fd=new FormData();fd.append('file',state.file);fd.append('project_json',JSON.stringify(projectSnapshot()));fd.append('prompt','Проанализируй чертёж как CNC-технолог. Определи материал, заготовку, размеры, резьбы, фаски, допуски, AF/лыски, тип обработки. Дай структурированный результат.');try{const r=await fetch('/api/analyze',{method:'POST',body:fd});const j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка анализа');state.analysis=j.response;applyIntelligence(j.drawing_intelligence,j.response);status.textContent='Анализ готов. Построение динамической геометрии…';try{await buildDynamicGeometry();status.textContent=`Готово · ${j.model} · ${j.mock?'mock':'live'} · контур ${Math.round((state.geometry.confidence||0)*100)}%`}catch(ge){state.geometry.warnings=[ge.message];status.textContent=`Анализ готов, контур требует ручной проверки: ${ge.message}`}persist();render()}catch(e){status.textContent='Ошибка: '+e.message;btn.disabled=false}}
function applyIntelligence(d,text=''){const t=text||'',get=re=>t.match(re)?.[1]?.replace(',','.')||'',set=(k,v)=>{if(v!==undefined&&v!==null&&String(v).trim()!=='')state.fields[k]=String(v).trim()};set('material',d?.material||get(/(?:Материал|material)[:\s]+([^\n]+)/i));const overall=d?.overall_length||get(/(?:общая длина|overall length)[^\d]*(\d+(?:[.,]\d+)?)/i);if(overall)setCanonicalOverall(overall,'analysis');set('blankDiameter',d?.blank_diameter||get(/(?:заготовк\w*|круг)[^Ø\d]*Ø\s*(\d+(?:[.,]\d+)?)/i));set('thread',d?.threads?.[0]?.designation||get(/\b(M\d+(?:[x×]\d+(?:[.,]\d+)?)?)/i));set('chamfer',d?.chamfers?.[0]?.designation||d?.chamfers_detected?.[0]||get(/(\d+(?:[.,]\d+)?\s*[x×]\s*45°?)/i));set('af',d?.af_features?.[0]?.across_flats||d?.secondary_features?.find?.(x=>/af|flat|hex/i.test(`${x.type} ${x.designation}`))?.dimension||get(/AF\s*(\d+(?:[.,]\d+)?)/i));set('tolerances',(d?.tolerances||[]).map(x=>x.designation||x).join(', '));set('mode',d?.recommended_mode||d?.recommended_stock_mode||'');const chain=d?.axial_segments?.length?{threadLength:d.axial_segments[0]?.length,stepLength:d.axial_segments[1]?.length,headLength:d.axial_segments[2]?.length,overallLength:overall}:parseChainFromText(t);if(chain){if(chain.overallLength!==null&&chain.overallLength!==undefined)setCanonicalOverall(chain.overallLength,'analysis-chain');setCanonicalSegment('threadLength',chain.threadLength,'analysis-chain');setCanonicalSegment('stepLength',chain.stepLength,'analysis-chain');setCanonicalSegment('headLength',chain.headLength,'analysis-chain')}else{const threadL=get(/(?:длина\s+резьб\w*|резьб\w*\s+участ\w*)[^\d]*(\d+(?:[.,]\d+)?)/i),stepL=get(/(?:ступен\w*[^\n]{0,40}(?:L|длин\w*))[^\d]*(\d+(?:[.,]\d+)?)/i),headL=get(/(?:головк\w*[^\n]{0,40}(?:L|длин\w*))[^\d]*(\d+(?:[.,]\d+)?)/i);if(threadL)setCanonicalSegment('threadLength',threadL,'analysis');if(stepL)setCanonicalSegment('stepLength',stepL,'analysis');if(headL)setCanonicalSegment('headLength',headL,'analysis')}syncDimensionsToFields();resetDependents(0)}
async function buildDynamicGeometry(){if(!state.file)throw new Error('Файл чертежа не выбран');const fd=new FormData();fd.append('file',state.file);if(state.fields.blankDiameter)fd.append('blank_diameter',state.fields.blankDiameter);if(state.fields.overallLength)fd.append('blank_length',state.fields.overallLength);fd.append('notes',state.analysis||'Построй геометрию только по текущему чертежу. Не используй шаблоны предыдущих деталей.');const r=await fetch('/api/contour-ai',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw new Error(j.detail||'Ошибка построения контура');const outer=(j.outer_contour||j.points||[]).map(p=>({x:Number(p.x),z:Number(p.z),type:p.type||'lineX'})).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.z));state.geometry={partType:j.part_type||'unknown',confidence:Number(j.confidence)||0,outerContour:outer,innerContours:j.inner_contours||[],holes:j.holes||[],secondaryFeatures:j.secondary_features||[],assumptions:j.assumptions||[],warnings:j.warnings||[],coordinateSystem:j.coordinate_system||{xMode:'diameter',zZero:'right_face'}};state.contour=outer.map(p=>[p.x,p.z]);const af=state.geometry.secondaryFeatures.find(x=>/flats|af|hex/i.test(`${x.type} ${x.designation}`));if(af?.dimension)state.fields.af=String(af.dimension);persist();return j}
function complete(i){state.done[i]=true;state.step=Math.min(9,i+1);persist();render()}
function moveRoute(i,d){let j=i+d;if(j<0||j>=state.route.length)return;[state.route[i],state.route[j]]=[state.route[j],state.route[i]];render()}
function renderInspector(){const f=state.fields;$('#summaryList').innerHTML=[['Название проекта',state.projectName],['Деталь',f.thread?'Деталь '+f.thread:'Не определена'],['Материал',f.material||'—'],['Станок','Tengyue CK52PT-Y'],['Стойка','Sinumerik 828D'],['Оператор','Єрошов Иван']].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('');const pct=state.done.filter(Boolean).length*10;$('#progressPercent').textContent=pct+'%';$('#progressBar').style.width=pct+'%';$('#progressList').innerHTML=STEPS.map((s,i)=>`<li class="${state.done[i]?'done':i===state.step?'current':''}"><span>${i+1} ${s}</span><span>${state.done[i]?'готово':i===state.step?'в работе':'заблокировано'}</span></li>`).join('')}
function renderNextStrip(){$('#nextStrip').innerHTML=`<h3>ЧТО БУДЕТ ДАЛЬШЕ?</h3><div class="next-cards">${STEPS.slice(state.step+1,state.step+7).map((s,i)=>`<div class="next-card"><b>${s}</b>${['Инженерная проверка','Базы и припуски','Токарный профиль','Фрезерный AF','Инструменты','Маршрут обработки'][i]||'Следующий этап'}</div>`).join('')}</div>`;$('#prevBtn').onclick=()=>{if(state.step>0){state.step--;render()}};$('#nextBtn').onclick=()=>{if(state.done[state.step]&&state.step<9){state.step++;render()}else alert('Сначала завершите текущий этап')}}
function drawStock(){const c=$('#stockCanvas');if(!c)return;const x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);x.fillStyle='#0a1523';x.fillRect(0,0,c.width,c.height);x.fillStyle='#52687d';x.fillRect(100,120,520,180);x.fillStyle='#12a8d5';x.fillRect(100,155,500,110);x.fillStyle='rgba(255,85,104,.55)';x.fillRect(100,120,340,35);x.fillRect(100,265,340,35);x.fillStyle='#d7e6f5';x.font='18px sans-serif';x.fillText('Серый — заготовка',30,35);x.fillText('Голубой — готовая геометрия',250,35);x.fillText('Красный — снимаемый материал',500,35)}
let simTimer=null;function drawSimulation(){const c=$('#simCanvas');if(!c)return;const x=c.getContext('2d'),p=+($('#simProgress')?.value||0)/100;x.clearRect(0,0,c.width,c.height);x.fillStyle='#07131f';x.fillRect(0,0,c.width,c.height);x.fillStyle='#4b5f73';x.fillRect(100,140,520,140);x.fillStyle='#20b9dc';x.fillRect(100,165,520*p,90);x.fillStyle='#f2b84b';x.beginPath();x.moveTo(90+520*p,130);x.lineTo(120+520*p,180);x.lineTo(60+520*p,180);x.fill();x.fillStyle='#fff';x.font='20px sans-serif';x.fillText(Math.round(p*100)+'%',350,50)}function playSimulation(){pauseSimulation();simTimer=setInterval(()=>{let r=$('#simProgress');if(!r)return pauseSimulation();r.value=Math.min(100,+r.value+2);drawSimulation();if(+r.value>=100){state.simulationReviewed=true;$('#simConfirm').checked=true;pauseSimulation()}},80)}function pauseSimulation(){if(simTimer){clearInterval(simTimer);simTimer=null}}
function buildFinalSnapshot(){return JSON.parse(JSON.stringify({version:'4.2.1-single-source-dimensions',projectName:state.projectName,projectId:state.projectId,created_at:new Date().toISOString(),finalizedAt:new Date().toISOString(),machine:{name:'Tengyue CK52PT-Y',control:'SINUMERIK 828D',axes:['X','Z','Y','C'],workflow:'ShopTurn'},done:state.done,analysis:state.analysis,fields:state.fields,dimensions:state.dimensions,dimensionChain:chainData(),stock:state.stock,contour:state.contour,geometry:state.geometry,afContour:state.afContour,tools:state.tools,route:state.route,simulationReviewed:state.simulationReviewed}))}
function finalizeResult(){const missing=STEPS.slice(0,9).filter((_,i)=>!state.done[i]);if(missing.length||!state.simulationReviewed)return alert('Сначала завершите этапы и подтвердите просмотр симуляции');state.finalizedAt=new Date().toISOString();state.finalResult=buildFinalSnapshot();state.finalResult.finalizedAt=state.finalizedAt;persist();showToast('Итоговый результат зафиксирован');render()}
async function downloadOperatorPdf(){if(!state.finalResult)return alert('Сначала зафиксируйте итоговый результат');const status=$('#pdfStatus'),button=document.querySelector('[data-type="pdf"]');if(button)button.disabled=true;if(status){status.className='check-card';status.textContent='Формирование PDF-карты оператора…'}try{const r=await fetch('/api/export/operator-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({snapshot:state.finalResult})});if(!r.ok){const j=await r.json().catch(()=>({}));throw new Error(j.detail||'Не удалось сформировать PDF')}const blob=await r.blob(),name=(state.projectName||'project').replace(/[^a-zа-яё0-9_-]+/gi,'_')+'_SINUMERIK_828D.pdf';downloadBlob(name,blob);if(status){status.className='check-card good';status.textContent='PDF сформирован и сохранён. Используйте его как карту ввода данных у стойки.'}showToast('PDF-карта оператора готова')}catch(error){if(status){status.className='check-card warning';status.textContent=error.message}alert(error.message)}finally{if(button)button.disabled=false}}
function exportProject(type){if(type==='pdf')return downloadOperatorPdf();if(!state.finalResult)return alert('Сначала зафиксируйте итоговый результат');const payload=state.finalResult;if(type==='json'){download('project-final.json',JSON.stringify(payload,null,2),'application/json')}else{const txt=type==='gcode'?`; ROZFOOD Personal AI Client\n; ВНИМАНИЕ: проверить на стойке и выполнить Dry Run\n; ${payload.route.join('\n; ')}\nG54\nM30\n`:`SINUMERIK 828D / ShopTurn\nПроект: ${payload.projectName}\nЗаготовка: Ø${payload.fields.blankDiameter} × ${payload.fields.overallLength}\nБазы: X0 ${payload.stock.x0}, Z0 ${payload.stock.z0}\n\n${payload.route.map((r,i)=>`${i+1}. ${r}`).join('\n')}`;download(type==='gcode'?'program.mpf':'shopturn_route.txt',txt,'text/plain')}}
function download(name,data,type){downloadBlob(name,new Blob([data],{type}))}function downloadBlob(name,blob){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}

